<?php if(in_array($document->status,['locked','ready_to_stamp','stamped'],true)&&$artifact){?><hr><h5><?php echo app_lang('local_xml_sealing'); ?></h5><div class="alert alert-warning"><?php echo app_lang('signed_xml_not_stamped'); ?></div><?php if($signature){?><div class="alert alert-success"><?php echo app_lang('local_signature_correct'); ?></div><?php if($can_signed_view){?><a href="<?php echo url_to('fiscal_signed_xml_view',$document->id); ?>" class="btn btn-default fiscal-signed-xml-view"><?php echo app_lang('view_signed_xml'); ?></a> <a href="<?php echo url_to('fiscal_signed_xml_download',$document->id); ?>" class="btn btn-default"><?php echo app_lang('download_signed_xml'); ?></a><?php }if($can_sign){echo form_open(get_uri('fiscal/stamping/verify-signed'),['id'=>'verify-signed-xml-form','class'=>'general-form d-inline']);?><input type="hidden" name="fiscal_document_id" value="<?php echo(int)$document->id; ?>"><button class="btn btn-default"><?php echo app_lang('verify_signed_xml'); ?></button><?php echo form_close();?><div id="signed-xml-verification-result" class="mt10"></div><?php }}elseif($document->status==='locked'&&$can_sign){echo form_open(get_uri('fiscal/invoices/sign'),['id'=>'local-signing-form','class'=>'general-form']);?><input type="hidden" name="document_id" value="<?php echo(int)$document->id; ?>"><input type="hidden" name="pre_xml_artifact_id" value="<?php echo(int)$artifact->id; ?>"><div class="form-group row"><label class="col-md-4"><?php echo app_lang('digital_seal_certificate'); ?></label><div class="col-md-8"><?php echo form_dropdown('certificate_id',[''=>'-']+$certificates,'',"class='select2 form-control' required"); ?><small><?php echo app_lang('csd_automatic_signing_notice'); ?></small></div></div><button class="btn btn-success"><?php echo app_lang('sign_xml_locally'); ?></button><?php echo form_close();}} ?>
