ument_id" value="<?php echo(int)$document->id; ?>"><button class="btn btn-danger" onclick="return confirm('<?php echo addslashes(app_lang('confirm_sandbox_stamp')); ?>');"><?php echo app_lang('stamp_test_cfdi'); ?></button><?php echo form_close();}else{?><div class="alert alert-warning"><?php echo htmlspecialchars($fiscal_status_view->visibleMessage); ?></div><?php }} ?>
