<script>$(document).ready(function(){var container=$('#ajaxModalContent'),loadFiscalView=function(url){$.ajax({url:url,type:'GET',data:{ajaxModal:1},success:function(html){container.html(html);container.find('button,a,input,select').filter(':visible').first().trigger('focus');},error:function(){appAlert.error('<?php echo addslashes(app_lang('something_went_wrong')); ?>');}});};$('#local-signing-form .select2').select2();$('.fiscal-review-back').on('click',function(){var button=$(this);button.trigger('blur');$.post(button.data('action-url'),{ajaxModal:1},function(html){container.html(html);container.find('button,a,input,select').filter(':visible').first().trigger('focus');});});$('.fiscal-signed-xml-view').on('click',function(e){e.preventDefault();loadFiscalView($(this).attr('href'));});$('#lock-fiscal-draft,#cancel-fiscal-draft,#generate-prexml-form,#validate-prexml-form,#stamp-cfdi-form').appForm({onSuccess:function(){location.reload();}});$('#local-signing-form').appForm({closeModalOnSuccess:false,onSuccess:function(result){appAlert.success(result.message);loadFiscalView(result.view_url||result.data.view_url);}});$('#verify-signed-xml-form').appForm({closeModalOnSuccess:false,onSuccess:function(result){var d=result.data||{},items=[['XML',d.xmlWellFormed],['XSD CFDI 4.0',d.xsdValid],['Certificado',d.certificateValid],['RFC',d.certificateMatchesIssuer],['NoCertificado',d.certificateNumberMatches],['Cadena original',d.originalChainGenerated],['Sello RSA-SHA256',d.signatureValid]];var html='<div class="alert alert-success">'+result.message+'</div><ul>';$.each(items,function(_,x){html+='<li>'+x[0]+': '+(x[1]?'<?php echo addslashes(app_lang('correct')); ?>':'<?php echo addslashes(app_lang('error')); ?>')+'</li>';});html+='</ul>';$('#signed-xml-verification-result').html(html);}});});</script>
